import { MRI_ARTIFACT_BLOCKS } from './technikMriArtifacts.js'

const DE_FROM_EN = new Map([
  ['Do not infer current legal limits, pregnancy-protection rules or national recommendations from this older summary.', 'Aus dieser älteren Zusammenfassung lassen sich keine aktuellen Grenzwerte, Regeln zum Strahlenschutz in der Schwangerschaft oder nationalen Empfehlungen ableiten.'],
  ['Keep each unit tied to its question: absorbed energy, radiation weighting, risk estimate, or scanner output index.', 'Ordnen Sie jede Einheit der passenden Frage zu: absorbierte Energie, Strahlungsgewichtung, Risikoschätzung oder Dosisanzeige des Scanners.'],
  ['Gy · absorbed dose', 'Gy · Energiedosis'],
  ['Energy deposited per mass; a physical quantity.', 'In Materie deponierte Energie pro Masse; eine physikalische Größe.'],
  ['Sv · equivalent/effective dose', 'Sv · Äquivalent-/Effektivdosis'],
  ['Weighted radiation-protection quantities; effective dose is an estimate for comparing population-level risk, not a direct measurement of an individual’s risk.', 'Gewichtete Größen des Strahlenschutzes. Die Effektivdosis schätzt das Risiko für Vergleiche auf Bevölkerungsebene, misst aber nicht direkt das individuelle Risiko.'],
  ['CTDIvol and DLP', 'CTDIvol und DLP'],
  ['Scanner-output indices for a protocol and scan length; neither alone gives organ dose or an individual patient’s risk.', 'Ausgabeindizes des Scanners für ein Protokoll und eine Scanlänge; keiner davon gibt allein die Organdosis oder das individuelle Patientenrisiko an.'],
  ['Air-kerma–area product; useful for documentation and comparison in radiography/fluoroscopy.', 'Luftkerma-Flächen-Produkt; dient in Radiographie und Durchleuchtung der Dokumentation und dem Vergleich.'],
  ['DLP = CTDIvol × scan length in consistent units. Conversion to effective dose is only an estimate and depends on body region and reference population.', 'DLP = CTDIvol × Scanlänge bei zueinander passenden Einheiten. Die Umrechnung in eine Effektivdosis ist nur eine Schätzung und hängt von Körperregion und Referenzpopulation ab.'],
  ['Practical rule: image only the necessary region, at quality sufficient to answer the diagnostic question. Protocol and parameter choices depend on the scanner, patient and task.', 'Praktische Regel: Nur die erforderliche Region mit ausreichender Qualität für die diagnostische Frage untersuchen. Protokoll und Parameter richten sich nach Gerät, Patient und Untersuchungsziel.'],
  ['Scan range', 'Scanbereich'], ['Limit start and end to the clinical question.', 'Begrenzen Sie Anfang und Ende des Scans auf die klinische Fragestellung.'],
  ['Centering and positioning', 'Zentrierung und Lagerung'], ['Correct positioning helps prevent repeats and modulation errors; follow the scanner protocol.', 'Eine korrekte Lagerung hilft, Wiederholungen und Fehler der Dosisregelung zu vermeiden; beachten Sie das Scannerprotokoll.'],
  ['kV, mAs and reconstruction', 'kV, mAs und Rekonstruktion'], ['Parameter changes affect penetration, contrast and noise; dose reduction must not cause inadequate diagnostic quality.', 'Parameteränderungen beeinflussen Durchdringung, Kontrast und Rauschen. Eine Dosisreduktion darf die diagnostische Bildqualität nicht unzureichend machen.'],
  ['Tube current changes the number of electrons; tube voltage sets their kinetic energy. Their interaction with the anode produces mostly heat and some X-rays.', 'Der Röhrenstrom beeinflusst die Zahl der Elektronen, die Röhrenspannung ihre kinetische Energie. Beim Auftreffen auf die Anode entstehen überwiegend Wärme und ein kleiner Anteil Röntgenstrahlung.'],
  ['A continuous spectrum from electron deceleration in the nuclear field.', 'Ein kontinuierliches Spektrum, das bei der Abbremsung von Elektronen im Coulombfeld des Atomkerns entsteht.'],
  ['Characteristic radiation', 'Charakteristische Strahlung'], ['Discrete photons after an inner-shell vacancy is filled; energy depends on anode material.', 'Diskrete Photonen entstehen, wenn eine Lücke in einer inneren Elektronenschale aufgefüllt wird; ihre Energie hängt vom Anodenmaterial ab.'],
  ['mA and kV', 'mA und kV'], ['mA mainly changes photon quantity; kV changes maximum energy and spectrum.', 'mA verändert vor allem die Photonenmenge; kV beeinflusst die maximale Photonenenergie und das Spektrum.'],
  ['The transmitted beam is attenuated by absorption and scatter. The image records attenuation differences; scatter reaching the detector reduces contrast.', 'Der durch den Körper tretende Strahl wird durch Absorption und Streuung abgeschwächt. Das Bild bildet Unterschiede der Abschwächung ab; Streustrahlung am Detektor mindert den Kontrast.'],
  ['Photoelectric', 'Photoeffekt'], ['The photon is absorbed; atomic-number differences can enhance contrast.', 'Das Photon wird absorbiert; Unterschiede der Ordnungszahl können den Bildkontrast erhöhen.'],
  ['Compton', 'Compton-Effekt'], ['The photon scatters and transfers part of its energy; an important source of scatter and contrast loss.', 'Das Photon wird gestreut und überträgt einen Teil seiner Energie; dieser Effekt trägt wesentlich zu Streustrahlung und Kontrastverlust bei.'],
  ['Coherent scatter', 'Kohärente Streuung'], ['Photon direction changes without ionization; its contribution depends on energy and context.', 'Die Photonenrichtung ändert sich ohne Ionisation; der Beitrag hängt von Energie und Untersuchungsbedingungen ab.'],
  ['In digital systems, X-ray signal is converted into an electrical signal and then image data. The conversion chain depends on detector type.', 'In digitalen Systemen wird das Röntgensignal zunächst in ein elektrisches Signal und anschließend in Bilddaten umgewandelt. Die Umwandlungskette hängt vom Detektortyp ab.'],
  ['A storage-phosphor plate is read and then erased.', 'Eine Speicherleuchtstoffplatte wird ausgelesen und anschließend gelöscht.'],
  ['Indirect DR', 'Indirekte digitale Radiographie'], ['A scintillator converts X-rays to light, then a photodetector converts light to charge.', 'Ein Szintillator wandelt Röntgenstrahlung in Licht um; ein Photodetektor wandelt das Licht anschließend in elektrische Ladung um.'],
  ['Direct DR', 'Direkte digitale Radiographie'], ['A semiconductor converts X-rays directly to charge.', 'Ein Halbleiter wandelt Röntgenstrahlung direkt in elektrische Ladung um.'],
  ['The tube and detectors record attenuation from many angles; computational reconstruction turns those data into slices. Volumetric acquisition enables multiplanar reformats.', 'Röhre und Detektoren erfassen die Abschwächung aus vielen Winkeln. Die rechnerische Rekonstruktion erzeugt daraus Schnittbilder; eine Volumenakquisition ermöglicht multiplanare Reformationen.'],
  ['Attenuation scale; water is the zero reference and air is approximately −1000. Measured values depend on energy, material and reconstruction.', 'Skala der Röntgenschwächung: Wasser ist der Nullpunkt, Luft liegt ungefähr bei −1000 HU. Messwerte hängen von Energie, Material und Rekonstruktion ab.'],
  ['Soft / sharp kernel', 'Weicher / scharfer Kernel'], ['A soft kernel smooths noise; a sharp kernel emphasizes edges and high-contrast detail and can increase noise.', 'Ein weicher Kernel glättet das Rauschen. Ein scharfer Kernel betont Kanten und kontrastreiche Details, kann aber das Rauschen verstärken.'],
  ['Measurements at different energies exploit energy- and material-dependent attenuation; outputs depend on scanner and reconstruction.', 'Messungen bei unterschiedlichen Energien nutzen die Energie- und Materialabhängigkeit der Abschwächung; die Ergebnisse hängen von Scanner und Rekonstruktion ab.'],
  ['CT perfusion', 'CT-Perfusion'], ['A time series after contrast bolus estimates tissue-flow parameters; motion, temporal/volumetric coverage and software model affect results.', 'Eine zeitliche Bildserie nach einem Kontrastmittelbolus schätzt Parameter der Gewebedurchblutung. Bewegung, zeitliche und räumliche Abdeckung sowie das Softwaremodell beeinflussen die Ergebnisse.'],
  ['Fluoroscopy provides live X-ray imaging. In DSA, a mask frame is subtracted from post-contrast frames to emphasize contrast-filled structures.', 'Die Durchleuchtung zeigt Röntgenbilder in Echtzeit. Bei der DSA wird ein Maskenbild von den Aufnahmen nach Kontrastmittelgabe subtrahiert, um kontrastierte Strukturen hervorzuheben.'],
  ['Motion', 'Bewegung'], ['Patient or device motion between mask and subsequent frames can create subtraction artefact.', 'Bewegungen des Patienten oder der Instrumente zwischen Masken- und Folgeaufnahme können Subtraktionsartefakte erzeugen.'],
  ['Device sizing', 'Größenangaben für Instrumente'], ['French describes catheter outer diameter; conversion to millimetres is omitted here to avoid rounding errors.', 'French bezeichnet den Außendurchmesser eines Katheters. Eine Umrechnung in Millimeter entfällt hier, um Rundungsfehler zu vermeiden.'],
  ['Radiation safety', 'Strahlenschutz'], ['Operating parameters, geometry and legal limits depend on patient, equipment and current regulation and require a separate lesson based on official sources.', 'Betriebsparameter, Geometrie und gesetzliche Grenzwerte hängen von Patient, Gerät und aktueller Rechtslage ab. Sie müssen in einer eigenen Lektion anhand offizieller Quellen geprüft werden.'],
  ['Protocol', 'Protokoll'], ['Specify the diagnostic question, required phase, bolus timing and anatomical coverage before scanning.', 'Legen Sie vor der Untersuchung die diagnostische Frage, erforderliche Kontrastphase, Bolustiming und anatomische Abdeckung fest.'],
  ['The PDF mentions RECIST 1.1; target-lesion definitions, thresholds and response rules must be checked against the official criteria and are not taught here yet.', 'Die PDF nennt RECIST 1.1. Definitionen der Zielläsionen, Schwellenwerte und Regeln zur Beurteilung des Ansprechens müssen anhand der offiziellen Kriterien geprüft werden und werden hier noch nicht gelehrt.'],
  ['After RF excitation, longitudinal magnetization recovers while transverse magnetization dephases. TR, TE, pulse sequence and field determine which tissue differences dominate.', 'Nach der HF-Anregung erholt sich die Längsmagnetisierung, während die Quermagnetisierung dephasiert. TR, TE, Pulssequenz und Feldstärke bestimmen, welche Gewebeunterschiede den Bildkontrast prägen.'],
  ['Longitudinal recovery; T1w is often useful for anatomy and fat is bright. Do not compare absolute signal across scanners.', 'Längsrelaxation: T1-gewichtete Bilder eignen sich häufig zur Anatomiebeurteilung; Fett erscheint hell. Absolute Signalintensitäten sind zwischen Scannern nicht direkt vergleichbar.'],
  ['T2 and T2*', 'T2 und T2*'], ['T2 reflects tissue transverse dephasing; field inhomogeneity adds signal loss in T2*. GRE is more susceptibility-sensitive than SE.', 'T2 beschreibt die transversale Dephasierung im Gewebe; Feldinhomogenitäten führen zusätzlich zum Signalverlust in T2*. GRE ist suszeptibilitätsempfindlicher als SE.'],
  ['Spin echo and GRE', 'Spin-Echo und GRE'], ['The 180° pulse in SE refocuses some dephasing from static inhomogeneity; GRE lacks this refocusing pulse.', 'Der 180°-Puls der SE-Sequenz rephasiert einen Teil der durch statische Feldinhomogenitäten verursachten Dephasierung; GRE besitzt diesen Rephasierungspuls nicht.'],
  ['IR, STIR and FLAIR', 'IR, STIR und FLAIR'], ['Inversion time is selected to null target tissue. STIR targets fat suppression and FLAIR free CSF suppression; tissue and contrast context matter.', 'Die Inversionszeit wird so gewählt, dass das Zielgewebe signalarm wird. STIR unterdrückt Fett, FLAIR den freien Liquor. Gewebe und Kontrastmittelkontext sind dabei zu berücksichtigen.'],
  ['Combining in-phase and opposed-phase images separates water and fat, producing water-only and fat-only reconstructions.', 'Durch Kombination von In-Phase- und Opposed-Phase-Bildern lassen sich Wasser und Fett trennen; es entstehen Water-only- und Fat-only-Rekonstruktionen.'],
  ['Field gradients at air/tissue, blood/tissue or metal interfaces can cause distortion and signal loss; GRE is more sensitive.', 'Feldgradienten an Luft-Gewebe-, Blut-Gewebe- oder Metallgrenzen können Verzerrungen und Signalverlust verursachen; GRE ist empfindlicher.'],
  ['Motion and chemical shift', 'Bewegung und Chemical Shift'], ['Motion during spatial encoding can create ghosting; water–fat frequency differences cause spatial displacement.', 'Bewegungen während der Ortskodierung können Geisterbilder verursachen; Frequenzunterschiede zwischen Wasser und Fett führen zu räumlicher Verschiebung.'],
  ['SAR and magnetic field', 'SAR und Magnetfeld'], ['Numerical values in this summary have not been checked against current protocols and regulations; do not use the PDF table to set patient limits.', 'Die Zahlenwerte dieser Zusammenfassung wurden nicht mit aktuellen Protokollen und Vorschriften abgeglichen. Verwenden Sie die PDF-Tabelle nicht zur Festlegung patientenbezogener Grenzwerte.'],
  ['Sequence names alone do not determine interpretation; consider preparation, flow direction, contrast timing and imaging limitations alongside signal.', 'Der Sequenzname allein bestimmt nicht die Interpretation. Berücksichtigen Sie zusätzlich Präparation, Flussrichtung, Kontrastmittelzeitpunkt und technische Grenzen.'],
  ['TOF / contrast MRA', 'TOF-/kontrastmittelgestützte MRA'], ['TOF is sensitive to inflowing unsaturated blood and can lose signal with slow or in-plane flow; contrast MRA depends on bolus timing.', 'TOF ist empfindlich für einströmendes, nicht gesättigtes Blut und kann bei langsamem oder schichtebenenparallelem Fluss Signal verlieren. Die kontrastmittelgestützte MRA hängt vom Bolustiming ab.'],
  ['DWI and ADC', 'DWI und ADC'], ['Correlate high DWI signal with ADC to avoid mistaking T2 shine-through for restricted diffusion.', 'Vergleichen Sie ein hohes DWI-Signal mit der ADC-Karte, damit ein T2-shine-through nicht mit einer Diffusionsrestriktion verwechselt wird.'],
  ['MR perfusion', 'MR-Perfusion'], ['T1- and T2*-based methods show different signal responses to a contrast bolus; metrics depend on model and protocol.', 'T1- und T2*-basierte Verfahren reagieren unterschiedlich auf einen Kontrastmittelbolus. Die Messparameter hängen von Modell und Protokoll ab.'],
  ['CINE and BOLD', 'CINE und BOLD'], ['CINE samples multiple phases of motion. BOLD measures oxygenation-related susceptibility changes with T2* contrast; an activation map is not an independent diagnosis.', 'CINE erfasst mehrere Bewegungsphasen. BOLD bildet sauerstoffabhängige Suszeptibilitätsänderungen mit T2*-Kontrast ab; eine Aktivierungskarte ist keine eigenständige Diagnose.'],
  ['The probe emits pulses and receives returning echoes. Return time informs depth and echo properties inform display; impedance boundaries and blood motion create diagnostic patterns.', 'Der Schallkopf sendet Impulse aus und empfängt zurückkehrende Echos. Die Laufzeit gibt Aufschluss über die Tiefe; Echoeigenschaften bestimmen die Darstellung. Impedanzgrenzen und Blutbewegung erzeugen diagnostische Muster.'],
  ['Reflection', 'Reflexion'], ['Acoustic-impedance differences at tissue boundaries create echoes.', 'Unterschiede der akustischen Impedanz an Gewebegrenzen erzeugen Echos.'],
  ['Shadowing and enhancement', 'Schallschatten und dorsale Schallverstärkung'], ['Strong attenuation behind a structure creates shadowing; low attenuation behind fluid can create enhancement.', 'Starke Abschwächung hinter einer Struktur erzeugt einen Schallschatten; geringe Abschwächung hinter Flüssigkeit kann eine dorsale Schallverstärkung bewirken.'],
  ['Doppler', 'Doppler'], ['Echo frequency shifts from moving red cells; beam-to-flow angle affects velocity estimation.', 'Die Bewegung der Erythrozyten verschiebt die Echo-Frequenz. Der Winkel zwischen Schallstrahl und Flussrichtung beeinflusst die Geschwindigkeitsschätzung.'],
])

const L = (de, en, fa) => ({ de: /[\u0600-\u06FF]/u.test(de) ? (DE_FROM_EN.get(en) || de) : de, en, fa })

// Draft mapped directly to Technik.pdf pp. 2–43. Legal limits and clinical
